CREATE OR REPLACE TABLE nokia_analytics.rivals_30y AS SELECT p.publication_number, p.application_number, p.family_id, p.country_code, p.kind_code, p.priority_date, p.filing_date, p.grant_date, ARRAY(SELECT DISTINCT a.name FROM UNNEST(p.assignee_harmonized) AS a WHERE REGEXP_CONTAINS(UPPER(a.name), r'\bCIENA\b|\bCISCO\b|ACACIA COMM|\bLUXTERA\b|ARISTA NETWORKS|\bHUAWEI\b') OR REGEXP_CONTAINS(a.name, r'华为')) AS owners, ARRAY(SELECT c.code FROM UNNEST(p.cpc) AS c) AS cpc_codes, (SELECT t.text FROM UNNEST(p.title_localized) AS t WHERE t.language = 'en' LIMIT 1) AS title_en FROM `patents-public-data.patents.publications` AS p WHERE p.filing_date >= 19961101 AND EXISTS (SELECT 1 FROM UNNEST(p.assignee_harmonized) AS a WHERE REGEXP_CONTAINS(UPPER(a.name), r'\bCIENA\b|\bCISCO\b|ACACIA COMM|\bLUXTERA\b|ARISTA NETWORKS|\bHUAWEI\b') OR REGEXP_CONTAINS(a.name, r'华为'));
